function P=build_REPS_interpretations(out,M,P,D,B,S)
%BUILD_REPS_INTERPRETATIONS Targeted engineering interpretation of retained data.
% Every inserted numerical value is also written to analysis_evidence.csv.
P.original_numerical_findings=P.calculated_numerical_findings;
P.engineering_analysis=strings(height(P),1);
evidence=struct('figure_id',{},'metric',{},'value',{},'source_cleaned_csv_files',{});
st=find(M.category=="Static load"); v=find(M.category=="Vibration"); c=find(M.category=="Load + vibration");
th=find(M.category=="Thermal"); cand=find(ismember(M.category,["Vibration","Frequency sweep","Load + vibration","Wind","Impact"]));
mu=@(ix,field) mean(M.(field)(ix),'omitnan');
sd=@(ix,field) std(M.(field)(ix),'omitnan');
pct=@(a,b) 100*(b-a)/a;
positions=[.25 .5 .75]; L=zeros(2,3); R=L; LS=L; RS=L;
for h=1:2, for j=1:3
    ix=find(M.category=="Static load" & M.source_subfolder=="918 load variation" & M.load_kg==h*.5 & M.load_position_norm==positions(j));
    assert(numel(ix)==3,'Static interpretation requires the audited repetitions.');
    L(h,j)=mu(ix,'lc_left_median'); R(h,j)=mu(ix,'lc_right_median'); LS(h,j)=sd(ix,'lc_left_median'); RS(h,j)=sd(ix,'lc_right_median');
end, end
vr=zeros(3,3); vs=vr; vp=zeros(3,2);
for j=1:3
    ix=v(M.vibration_pwm(v)==64*j); assert(numel(ix)==3);
    for h=1:3, names=["rms_x_g","rms_y_g","rms_z_g"]; vr(j,h)=mu(ix,names(h)); vs(j,h)=sd(ix,names(h)); end
    vp(j,:)=[mu(ix,'peak_z_g'),sd(ix,'peak_z_g')];
end

desc(1,"Combined load/vibration dominates the retained design: %d of %d recordings (%.1f percent), compared with %d static and %d unloaded-vibration runs. This balance supports condition-specific comparisons but gives greater descriptive weight to the combined campaign. The two thermal files represent one interrupted session, not replication of environmental behavior. Coverage therefore supports identifying candidate sensor-response relationships; it does not establish a balanced validation dataset or justify pooling acquisition batches.", ...
    ["combined_runs","retained_runs","combined_percent","static_runs","unloaded_runs"],[numel(c),height(M),100*numel(c)/height(M),numel(st),numel(v)]);
desc(2,"Known mass and PWM metadata are present for %d recordings; %d thermal segments remain explicitly unknown. PWM 192 has %d recordings, versus %d at PWM 64. These are acquisition counts, not evidence of stronger excitation or better repeatability. Since the mass, position and motor settings are not equally represented, an unstratified average would mix operating conditions and batch effects. Later response comparisons therefore retain matched conditions.", ...
    ["known_mass_pwm_runs","unknown_thermal_segments","pwm192_runs","pwm64_runs"],[nnz(isfinite(M.load_kg)&isfinite(M.vibration_pwm)),numel(th),nnz(M.vibration_pwm==192),nnz(M.vibration_pwm==64)]);
t2=find(M.test_id=="THERMAL_01_PART2");
desc(3,"The median timestamp increment suggests %.3f Hz, but the median effective recording rate is only %.3f samples/s: gaps reduce temporal coverage despite a nominally fast clock. Thermal segment 2 is the strongest duration anomaly, with a %.3f s timestamp span but only %.3f s between finite sensor endpoints. Its leading missing interval depresses the effective rate and must not be interpreted as measured slow sampling. Neither histogram alone establishes FFT eligibility; continuity is audited separately.", ...
    ["median_interval_fs_Hz","median_effective_samples_per_s","thermal2_timestamp_span_s","thermal2_valid_span_s"], ...
    [median(M.median_fs_Hz),median(M.effective_fs_Hz),M.duration_s(t2),M.valid_span_s(t2)]);
tc=find(M.test_id=="T0236");
desc(4,"High average coverage conceals a complete channel loss: T0236 contains %d samples but no finite values in any of its three temperature channels. Its valid acceleration cannot restore the missing environmental context. All %d retained recordings carry CHECK status, so coverage is not equivalent to accepted measurement quality. Missing channels and timestamp gaps require separate controls; the recovered T0236 spectrum remains useful only as a conditional acceleration observation, without a simultaneous temperature comparison.", ...
    ["T0236_samples","CHECK_recordings"],[height(D{tc}.T),nnz(M.qc_status=="CHECK")]);

ix=sourceRows(5); k=ix(M.test_id(ix)=="T0173");
desc(5,"At the same 0.5 kg mass, the representative left-cell medians decrease from %.0f counts under left loading to %.0f under right loading, while the opposite channel increases. This is consistent with location-dependent transfer through the bridge and supports using both channels to distinguish position. However, T0173 also contains abrupt late-record changes: its right-channel maximum-minus-minimum span is %.0f counts. Such excursions are not explained by a static mass label and could reflect load movement, mounting changes or acquisition artifacts. The stable portions and run medians should therefore not be taken as proof that the entire waveform is trustworthy. A synchronized loading log and calibrated channels are needed to separate mechanical response from measurement faults.", ...
    ["left_loading_representative_L_counts","right_loading_representative_L_counts","T0173_right_span_counts"], ...
    [M.lc_left_median(ix(M.load_position_norm(ix)==.25)),M.lc_left_median(k),max(D{k}.T.loadcell_right_raw)-min(D{k}.T.loadcell_right_raw)]);
desc(6,"Doubling applied mass from 0.5 to 1 kg produces strongly position-dependent count changes within September 18. Left-cell means of run medians rise %.1f percent for left loading and %.1f percent at center, but only %.2f percent for right loading. Conversely, the right-cell change is only %.2f percent under left loading and %.1f percent under right loading. Thus both channels increase over the two tested mass levels, but their sensitivities are far from interchangeable. A nearby load path and channel-specific offsets or gains could produce this pattern; it is not a calibrated force distribution. The separate September 25 0.25 kg series cannot establish a common linear calibration, and two mass levels cannot establish general linearity.", ...
    ["left_mass_change_at_left_pct","left_mass_change_at_center_pct","left_mass_change_at_right_pct","right_mass_change_at_left_pct","right_mass_change_at_right_pct"], ...
    [pct(L(1,1),L(2,1)),pct(L(1,2),L(2,2)),pct(L(1,3),L(2,3)),pct(R(1,1),R(2,1)),pct(R(1,3),R(2,3))]);
desc(7,"Output asymmetry is not a universal monotonic function of mass. When mass doubles, left-minus-right counts increase by %.0f under left loading, but decrease by %.0f at center and %.0f under right loading. The direction depends on which channel acquires the larger incremental response. This supports treating mass and position jointly in a future measurement model, rather than using a single pooled asymmetry-to-mass curve. The center value remains negative at both masses, showing that a centered load does not zero this uncalibrated difference. Unequal channel offsets, gains and mounting compliance are plausible contributors. Without tare and independent calibration, neither the sign nor its magnitude quantifies unequal support forces.", ...
    ["mass_asym_change_left_counts","mass_asym_decrease_center_counts","mass_asym_decrease_right_counts"], ...
    [(L(2,1)-R(2,1))-(L(1,1)-R(1,1)),-((L(2,2)-R(2,2))-(L(1,2)-R(1,2))),-((L(2,3)-R(2,3))-(L(1,3)-R(1,3)))]);
cv=[LS(:)./L(:);RS(:)./R(:)]*100;
desc(8,"The September 18 run medians are relatively reproducible compared with their absolute count levels: between-run coefficients of variation range from %.3f to %.3f percent. The largest value belongs to the right channel at 1 kg/right loading, where the standard deviation is %.0f counts, substantially larger than the %.0f-count standard deviation at 0.5 kg/right loading. This localized loss of repeatability deserves a mounting and acquisition check before fitting position sensitivity. These percentages describe raw medians, whose large offsets can make relative scatter appear small. Stable medians also suppress isolated excursions visible in time histories. No acceptance tolerance or calibration uncertainty was specified, so the data support descriptive repeatability, not a declaration that measurement performance is acceptable.", ...
    ["static_cv_min_pct","static_cv_max_pct","right_1kg_right_sd_counts","right_halfkg_right_sd_counts"],[min(cv),max(cv),RS(2,3),RS(1,3)]);
desc(9,"Moving a 1 kg load from left to right decreases the left-channel mean of run medians from %.0f to %.0f counts (%.1f percent), while increasing the right channel from %.0f to %.0f counts (%.1f percent). The center measurements lie between the endpoints. The same opposite ordering occurs at 0.5 kg in September 18 and at 0.25 kg in September 25, making position sensitivity more consistent than an across-batch mass calibration. Redistribution of the load path is a plausible mechanism, although sensor mounting and channel gains contribute to the observed scale. Because these are raw counts with unknown tare, the relative changes cannot be interpreted as support-reaction percentages. Independent position trials would be needed to test prediction accuracy.", ...
    ["1kg_leftposition_L_counts","1kg_rightposition_L_counts","L_position_decrease_pct","1kg_leftposition_R_counts","1kg_rightposition_R_counts","R_position_increase_pct"], ...
    [L(2,1),L(2,3),-pct(L(2,1),L(2,3)),R(2,1),R(2,3),pct(R(2,1),R(2,3))]);
desc(10,"Asymmetry falls consistently as the load moves right within each mass/batch stratum. At 1 kg the group means are %.0f, %.0f and %.0f counts for left, center and right, respectively. This ordered separation is potentially useful for identifying load location from a pair of sensors. It also reveals why the channel difference must not be interpreted as a force balance: the center result is far from zero, and all three September 25 0.25 kg positions have negative differences. Channel offsets or unequal gains can shift the entire relation without destroying its ordering. The trend is encouraging for a calibrated measurement model, but repetition scatter, acquisition artifacts and limited independent positions prevent claiming validated localization.", ...
    ["1kg_asym_left_counts","1kg_asym_center_counts","1kg_asym_right_counts"],[L(2,1)-R(2,1),L(2,2)-R(2,2),L(2,3)-R(2,3)]);
ratio=zeros(2,3); for h=1:2, for j=1:3
    ids=st(M.source_subfolder(st)=="918 load variation"&M.load_kg(st)==h*.5&M.load_position_norm(st)==positions(j)); ratio(h,j)=mean(M.raw_left_share(ids));
end,end
desc(11,"For the 1 kg series, the normalized left raw-signal contribution decreases from %.3f at left loading to %.3f at center and %.3f at right. The corresponding 0.5 kg endpoints are %.3f and %.3f. The consistent direction compresses the two-channel position pattern into a bounded descriptor, but the center ratio is not 0.5 and the relation shifts with mass. These deviations are expected to be sensitive to nonzero sensor offsets and unequal gains, not just mechanics. The ratio may be useful as an empirical feature after calibration and controlled validation, but it is not a physical load-sharing fraction. Using it directly as a support reaction would discard the very offset and sensitivity information that these measurements show is important.", ...
    ["share_1kg_left","share_1kg_center","share_1kg_right","share_halfkg_left","share_halfkg_right"],[ratio(2,:),ratio(1,1),ratio(1,3)]);

ix=sourceRows(12); vals=zeros(1,3); for j=1:3, vals(j)=M.rms_z_g(ix(M.vibration_pwm(ix)==64*j)); end
desc(12,"The selected waveforms separate a largely steady acceleration offset from much smaller dynamic fluctuations. Their detrended z RMS values are %.5f, %.5f and %.5f g at PWM 64, 128 and 192. The highest command produces sustained broader fluctuations, whereas the PWM 128 representative includes a short, conspicuous excursion near the latter part of the record. This difference illustrates why RMS and maximum amplitude need not rank commands identically: a brief transient can dominate the peak without dominating the energy averaged over the recording. Increased forcing is plausible at higher command, but PWM does not identify excitation force or frequency. These are median-RMS representatives, not synchronized trials, and earlier cleaning may have altered individual spikes.", ...
    ["representative_PWM64_rms_g","representative_PWM128_rms_g","representative_PWM192_rms_g"],vals);
desc(13,"Mean unloaded z RMS increases monotonically from %.5f g at PWM 64 to %.5f g at 128 and %.5f g at 192. The increases are %.1f percent for 64-to-128 and %.1f percent for 128-to-192; the highest command is %.1f percent above the lowest. The first increase is smaller than the PWM 64 between-run standard deviation of %.5f g, so that step is weak evidence of a repeatable change. The high-command separation is more pronounced relative to the plotted repetition spread. Greater excitation is a plausible explanation, but motor force, speed and structural response are not independently measured. These three-repetition results characterize sensitivity under this acquisition setup, not a calibrated or statistically validated command-response law.", ...
    ["PWM64_mean_rms_g","PWM128_mean_rms_g","PWM192_mean_rms_g","64to128_pct","128to192_pct","64to192_pct","PWM64_sd_g"], ...
    [vr(:,3)',pct(vr(1,3),vr(2,3)),pct(vr(2,3),vr(3,3)),pct(vr(1,3),vr(3,3)),vs(1,3)]);
desc(14,"Peak response is nonmonotonic: the mean observed maximum is %.5f g at PWM 64, %.5f g at 128 and %.5f g at 192. The last step decreases the peak by %.1f percent even though RMS increases. This is a substantive counterexample to treating a higher motor command as a uniformly larger response. Short-lived excursions and differences in waveform concentration can reverse peak rankings while sustained fluctuations increase. PWM 64 peaks are especially variable, with a between-run standard deviation of %.5f g, compared with %.5f g at PWM 128. No extra smoothing was applied here, but upstream spike filtering remains a limitation. Peak-based alarm or model features therefore need event-level provenance and repeatability checks, rather than relying on command alone.", ...
    ["PWM64_mean_peak_g","PWM128_mean_peak_g","PWM192_mean_peak_g","peak128to192_decrease_pct","PWM64_peak_sd_g","PWM128_peak_sd_g"], ...
    [vp(:,1)',-pct(vp(2,1),vp(3,1)),vp(1,2),vp(2,2)]);
desc(15,"Dynamic response is not confined to the recorded z axis. At PWM 192, mean x/y/z RMS is %.5f/%.5f/%.5f g; y exceeds z by %.1f percent. At PWM 64, z is %.2f times x, so the dominant measured direction changes with command. From the lowest to highest PWM, x and y increase by factors %.2f and %.2f, larger than the z factor %.2f. Direction-dependent excitation, sensor orientation and changes in structural motion could all contribute. The result argues for retaining all three axes in future system identification rather than reducing the measurement to z alone. It does not establish a mode shape: spatial measurements, orientation verification and excitation characterization are missing.", ...
    ["PWM192_x_g","PWM192_y_g","PWM192_z_g","PWM192_y_over_z_pct","PWM64_z_to_x","x_high_low_factor","y_high_low_factor","z_high_low_factor"], ...
    [vr(3,:),pct(vr(3,3),vr(3,2)),vr(1,3)/vr(1,1),vr(3,1)/vr(1,1),vr(3,2)/vr(1,2),vr(3,3)/vr(1,3)]);
desc(16,"Only %d of %d candidates passes the unchanged continuity screen. T0236 supplies a %.3f s interval; the other candidates have maximum continuous spans no longer than %.3f s. Recurrent acquisition gaps, rather than a low nominal sampling rate, therefore constrain frequency analysis. Interpolating through those gaps would introduce assumptions about unmeasured vibration. The isolated accepted interval permits a response spectrum, but it cannot establish spectral repeatability across PWM, load or position.", ...
    ["accepted_candidates","candidate_count","T0236_interval_s","other_max_interval_s"], ...
    [nnz(M.spectral_eligible(cand)),numel(cand),M.longest_interval_s(tc),max(M.longest_interval_s(setdiff(cand,tc)))]);
desc(17,"The audit now distinguishes data eligibility from software availability: %d candidates fail timing and %d passes for base-MATLAB FFT. The earlier rejection of the valid interval was an unnecessarily restrictive toolbox gate, not a defect in its timestamps. A directly evaluated periodic Hann window and built-in fft recover that result without changing the continuity thresholds. Welch PSD and spectrograms remain omitted because their toolbox functions are not installed; unavailable software is not used to excuse invalid timing elsewhere.", ...
    ["timing_rejected_candidates","baseFFT_accepted_candidates"],[nnz(~M.spectral_eligible(cand)),nnz(M.spectral_eligible(cand))]);

g=@(mass,pos,pwm) find(M.category=="Load + vibration" & M.load_kg==mass & M.load_position_norm==pos & M.vibration_pwm==pwm);
a=mu(g(.25,.25,64),'rms_z_g'); b=mu(g(.5,.25,64),'rms_z_g'); d=mu(g(1,.25,64),'rms_z_g');
e=mu(g(.25,.5,192),'rms_z_g'); f=mu(g(1,.5,192),'rms_z_g');
desc(18,"Loading does not produce a universal increase in vibration response. At left loading/PWM 64, mean RMS changes %.5f to %.5f to %.5f g as mass increases from 0.25 to 0.5 to 1 kg: a %.1f percent decrease followed by a %.1f percent increase. At center/PWM 192, the endpoint change instead decreases %.1f percent. Changes in mass distribution, contact conditions or excitation coupling could alter the measured dynamics in either direction; the data do not isolate those mechanisms. The left/PWM 64 repetition spread is large, and one center/1 kg/PWM 64 condition has only a single recording. Thus mass must be interpreted together with position and command, and neither a monotonic mass law nor a resonance shift is established.", ...
    ["left64_quarter_rms_g","left64_half_rms_g","left64_one_rms_g","left64_first_decrease_pct","left64_second_increase_pct","center192_mass_decrease_pct"], ...
    [a,b,d,-pct(a,b),pct(b,d),-pct(e,f)]);
centerLower=0; for mass=[.25 .5 1],for pwm=[64 128 192], centerLower=centerLower+(mu(g(mass,.5,pwm),'rms_z_g')<min(mu(g(mass,.25,pwm),'rms_z_g'),mu(g(mass,.75,pwm),'rms_z_g')));end,end
a=mu(g(.5,.25,128),'rms_z_g'); b=mu(g(.5,.5,128),'rms_z_g'); d=mu(g(.5,.75,128),'rms_z_g');
desc(19,"Center loading gives the smallest mean z RMS in all %d matched mass/PWM combinations. For example, at 0.5 kg/PWM 128, left/center/right means are %.5f/%.5f/%.5f g, placing center %.1f percent below left and %.1f percent below right. This repeated ordering is stronger descriptive evidence of position sensitivity than a pooled mass trend. Load placement may alter local motion, load transfer or coupling between the motor and bridge, but the sensor location and input force are insufficiently characterized to identify a mechanism or modal node. Common vertical scales make the comparison explicit. Small repetition counts and variable scatter at the edge positions still require independent replication before position-dependent dynamic predictions can be validated.", ...
    ["center_lower_combinations","half128_left_g","half128_center_g","half128_right_g","center_below_left_pct","center_below_right_pct"], ...
    [centerLower,a,b,d,-pct(a,b),-pct(d,b)]);
ix=sourceRows(20); left=ix(M.load_position_norm(ix)==.25); right=ix(M.load_position_norm(ix)==.75);
desc(20,"The representative load-cell levels remain strongly separated by position during commanded vibration. The right-loaded representative has a left-cell median of %.0f counts, whereas the two left-loaded representatives span %.0f--%.0f counts. The opposite-channel levels reverse this spatial contrast. Their nearly steady raw baselines indicate that the plotted scale is dominated by sustained loading and sensor offsets, not by the much smaller acceleration fluctuations. The figure cannot isolate PWM because the PWM 192 example is right-loaded and the lower-command examples are left-loaded. Moreover, apparent flatness at this scale does not prove zero dynamic load. Calibrated, sufficiently fast load-cell acquisition and matched-position comparisons would be required to quantify vibration-induced support-force variation.", ...
    ["right_loaded_representative_L_counts","left_loaded_L_min_counts","left_loaded_L_max_counts"], ...
    [M.lc_left_median(right),min(M.lc_left_median(left)),max(M.lc_left_median(left))]);
off=zeros(3,2); on=off;
for j=1:3
    ix=find(M.source_subfolder=="9_25_loadvib"&M.load_kg==.25&M.load_position_norm==positions(j)&M.vibration_pwm==0);
    off(j,:)=[mu(ix,'rms_z_g'),sd(ix,'rms_z_g')]; ix=g(.25,positions(j),192); on(j,:)=[mu(ix,'rms_z_g'),sd(ix,'rms_z_g')];
end
desc(21,"The matched 0.25 kg off/on comparison is directionally inconsistent. At PWM 192 relative to PWM 0, mean RMS changes by %+.1f percent at left, %+.1f percent at center and %+.1f percent at right. The left decrease is counterintuitive if motor operation is assumed to add a fixed independent vibration component, but the off-run standard deviation (%.5f g) is large relative to that difference. Center increases from %.5f to %.5f g and shows a clearer descriptive separation. Different ambient motion, mounting or intermittent excitation could explain part of the variability. These are separate runs, not paired before/after measurements; the OFF condition is not guaranteed motionless. The results reject a simple universal command multiplier without proving a causal position effect.", ...
    ["left_off_to192_pct","center_off_to192_pct","right_off_to192_pct","left_off_sd_g","center_off_mean_g","center_on_mean_g"], ...
    [pct(off(1,1),on(1,1)),pct(off(2,1),on(2,1)),pct(off(3,1),on(3,1)),off(1,2),off(2,1),on(2,1)]);

% Endpoint changes use medians in the first/last five seconds of occupied bins.
delta=zeros(numel(th),5); for h=1:numel(th)
    b=B{th(h)}; fields=["temp_left_C","temp_center_C","temp_right_C","loadcell_left_raw","loadcell_right_raw"];
    first=b.time_s<=min(b.time_s)+5; last=b.time_s>=max(b.time_s)-5;
    delta(h,:)=median(b{last,fields},1,'omitnan')-median(b{first,fields},1,'omitnan');
end
F=readtable(fullfile(out,'thermal_fits.csv'),'TextType','string');
sl=zeros(2,5); rr=sl; sensors=["loadcell_left_raw","loadcell_right_raw","accel_x_g","accel_y_g","accel_z_g"];
for h=1:2,for j=1:5,k=find(F.segment==M.test_id(th(h))&F.sensor==sensors(j));sl(h,j)=F.slope_per_C(k);rr(h,j)=F.r_squared(k);end,end
desc(22,"The first segment is predominantly a localized heating observation: first-to-last five-second median temperatures change by %+.2f, %+.2f and %+.2f deg C at left, center and right. The second segment cools, with corresponding changes of %+.2f, %+.2f and %+.2f deg C. The much larger left-side heating excursion indicates a spatial thermal gradient rather than uniform bridge temperature. Such gradients can influence sensor electronics, mounting stresses and apparent mechanical response differently at each location. Both segments belong to one session, and the missing interruption prevents observing the transition directly. Segment-specific offsets and different temperature ranges therefore preclude treating these data as repeated heating/cooling cycles or identifying hysteresis from a continuous loop.", ...
    ["heat_left_delta_C","heat_center_delta_C","heat_right_delta_C","cool_left_delta_C","cool_center_delta_C","cool_right_delta_C"],[delta(1,1:3),delta(2,1:3)]);
desc(23,"The right load cell has a much more coherent temperature association during cooling: slope %.1f counts/deg C with R-squared %.3f, compared with %.1f and %.3f during heating. The left channel is less consistent: its heating slope is %.1f counts/deg C but R-squared is only %.3f; the cooling values are %.1f and %.3f. The conspicuous heating-segment excursions weaken a single straight-line description even after median binning. Differential sensor electronics, mounting expansion and changing mechanical preload are plausible contributors, but the channels cannot be calibrated thermally from these associations alone. In particular, the strong cooling fit may arise because both output and temperature drift with elapsed time. Independent controlled cycles and fixed loading are needed to distinguish temperature effects from shared temporal trends.", ...
    ["cool_R_slope_counts_per_C","cool_R_R2","heat_R_slope_counts_per_C","heat_R_R2","heat_L_slope_counts_per_C","heat_L_R2","cool_L_slope_counts_per_C","cool_L_R2"], ...
    [sl(2,2),rr(2,2),sl(1,2),rr(1,2),sl(1,1),rr(1,1),sl(2,1),rr(2,1)]);
desc(24,"Acceleration-level associations are axis dependent and do not behave as a single thermal offset. The x slope is positive in both segments: %.6f and %.6f g/deg C, with R-squared %.3f and %.3f. The z slopes are negative, %.6f and %.6f g/deg C, but heating explains little of the z variation (R-squared %.3f). Cooling y is almost unrelated to left temperature (R-squared %.3f). Quantized bands and large heating-segment excursions further limit a smooth linear model. Electronics drift is plausible, but these levels also contain gravity projection, orientation and mechanical motion; a small tilt can mimic an acceleration offset. Environmental compensation should therefore retain axis-specific hypotheses and test them on controlled independent sessions, rather than subtracting these slopes directly from dynamic data.", ...
    ["heat_x_slope_g_per_C","cool_x_slope_g_per_C","heat_x_R2","cool_x_R2","heat_z_slope_g_per_C","cool_z_slope_g_per_C","heat_z_R2","cool_y_R2"], ...
    [sl(1,3),sl(2,3),rr(1,3),rr(2,3),sl(1,5),sl(2,5),rr(1,5),rr(2,4)]);
desc(25,"The elapsed-time view distinguishes persistent drift from transient excursions. Heating-segment final-minus-initial median changes are %+.0f counts on the left and %+.0f on the right; cooling changes are %+.0f and %+.0f counts. The cooling right channel decreases relatively smoothly, while the left drifts weakly upward despite cooling, consistent with the opposite fitted slope signs. Heating instead contains large short-lived departures superimposed on the endpoint changes. Thermally induced preload changes or sensor drift are possible explanations, but the excursions also require acquisition and handling review. Separate segment baselines prevent the large inter-segment offset from being misrepresented as observed continuous drift. Endpoint summaries are therefore useful for comparing within-segment behavior, but cannot partition thermal, mechanical and instrumentation contributions.", ...
    ["heat_L_endpoint_counts","heat_R_endpoint_counts","cool_L_endpoint_counts","cool_R_endpoint_counts"],[delta(1,4:5),delta(2,4:5)]);
desc(26,"The fitted sensitivity comparison highlights nontransferability between the two segments. The right-cell cooling slope is %.2f times its heating slope, with R-squared improving from %.3f to %.3f. The absolute left-cell heating slope is %.2f times its cooling slope, yet its heating R-squared is only %.3f; a large slope therefore does not necessarily indicate a reliable temperature relationship. Acceleration axes also differ in sign and fit quality. These contrasts suggest that a single coefficient per sensor would confound operating state, temperature range and elapsed-time effects. The strongest fit is a useful hypothesis for a controlled follow-up experiment, not a validated correction. Compensation should be evaluated by its prediction error on independent fixed-load thermal cycles, with sensor-specific uncertainty and residual drift reported.", ...
    ["R_cool_heat_slope_factor","R_heat_R2","R_cool_R2","L_heat_cool_abs_slope_factor","L_heat_R2"], ...
    [sl(2,2)/sl(1,2),rr(1,2),rr(2,2),abs(sl(1,1)/sl(2,1)),rr(1,1)]);

ix=sourceRows(27); wind0=ix(M.category(ix)=="Wind"&M.vibration_pwm(ix)==0); wind192=ix(M.category(ix)=="Wind"&M.vibration_pwm(ix)==192); imp=ix(M.category(ix)=="Impact");
desc(27,"The representative no-motor wind record reaches %.3f g, compared with %.3f g in the representative impact record and %.3f g in the PWM 192 wind record. The larger wind-labelled transient is therefore not consistent with ranking disturbance severity by label alone. The no-motor wind and impact traces contain localized bursts followed by visibly smaller oscillations, whereas the motor-assisted wind trace has a more persistent low-amplitude background. This is compatible with different forcing histories and subsequent decay, but labels do not specify the input waveform. Peaks may also be affected by upstream cleaning and acquisition gaps. Without synchronized impact timing or measured wind forcing, no reliable decay constant, damping ratio or causal wind-versus-impact comparison can be extracted.", ...
    ["representative_wind0_peak_g","representative_impact_peak_g","representative_wind192_peak_g"], ...
    [M.peak_z_g(wind0),M.peak_z_g(imp),M.peak_z_g(wind192)]);
impact=find(M.category=="Impact"); w0=find(M.category=="Wind"&M.vibration_pwm==0); w192=find(M.category=="Wind"&M.vibration_pwm==192);
desc(28,"Impact recordings are highly heterogeneous: observed z peaks span %.3f--%.3f g, a factor of %.1f. The strongest impact, T0258, has RMS %.4f g, while the no-motor wind recording T0256 has RMS %.4f g and a smaller peak of %.3f g. Thus peak and RMS emphasize different features of the excitation: concentrated impulses versus more sustained or repeated motion. The two PWM 192 wind records have much lower RMS, %.4f and %.4f g, despite motor operation. Unknown wind intensity, handling and event timing prevent interpreting this as motor-induced suppression. These results argue for recording forcing and event metadata before training a disturbance classifier or response model; current labels are insufficient proxies for excitation magnitude or duration.", ...
    ["impact_min_peak_g","impact_max_peak_g","impact_peak_factor","T0258_rms_g","T0256_rms_g","T0256_peak_g","T0253_rms_g","T0254_rms_g"], ...
    [min(M.peak_z_g(impact)),max(M.peak_z_g(impact)),max(M.peak_z_g(impact))/min(M.peak_z_g(impact)),M.rms_z_g(find(M.test_id=="T0258"&M.category=="Impact")),M.rms_z_g(w0),M.peak_z_g(w0),M.rms_z_g(w192)']);
pre=zeros(1,3); post=pre; energy=pre;
for h=1:3
    k=impact(h); t=D{k}.t; z=D{k}.z(:,3); [~,pk]=max(abs(z)); rel=t-t(pk); bins=floor(rel); u=unique(bins(isfinite(z))); vals=nan(size(u));
    for j=1:numel(u), vals(j)=sqrt(mean(z(bins==u(j)).^2,'omitnan')); end
    centers=u+.5; pre(h)=median(vals(centers>=-5&centers<-1),'omitnan'); post(h)=median(vals(centers>1&centers<=5),'omitnan');
    energy(h)=100*sum(z(abs(rel)<=1).^2,'omitnan')/sum(z.^2,'omitnan');
end
desc(29,"The largest-event neighborhoods concentrate %.1f, %.1f and %.1f percent of squared residual samples within plus/minus one second in T0255, T0257 and T0258, respectively. The stronger impact records are therefore dominated by brief bursts rather than uniform vibration. Their envelopes fall after the largest burst, but secondary peaks and nonzero residual motion prevent a unique free-decay interpretation. For T0258, the median one-second RMS is %.5f g in the pre-feature window and %.5f g afterward; the post-window is not a demonstrated return to baseline. Alignment uses the largest measured residual, not a recorded trigger. Missing samples, upstream filtering and unknown repeated forcing preclude reliable damping estimation; the apparent envelope is descriptive evidence for better event-synchronized tests.", ...
    ["T0255_event_energy_pct","T0257_event_energy_pct","T0258_event_energy_pct","T0258_pre_rms_g","T0258_post_rms_g"],[energy,pre(3),post(3)]);
% Map extrema are means of matched runs, not extrema of individual runs.
means=[]; keys=[]; for pos=positions,for mass=[.25 .5 1],for pwm=[64 128 192],means(end+1)=mu(g(mass,pos,pwm),'rms_z_g');keys(end+1,:)=[mass,pos,pwm];end,end,end %#ok<AGROW>
[lo,il]=min(means);[hi,ih]=max(means);
desc(30,"The same-batch response map is structured primarily by position rather than a uniformly increasing mass or PWM scale. The lowest condition mean is %.5f g at %.2f kg, normalized position %.2f, PWM %.0f; the highest is %.5f g at %.2f kg, position %.2f, PWM %.0f, a factor of %.2f. Center loading remains lower than both edges across the matched grid, while edge responses vary nonmonotonically with mass. This supports retaining interactions among operating variables in future identification instead of fitting independent scalar corrections. However, the grid contains only a few repetitions per cell and one singleton. Apparent spatial structure is a hypothesis about this setup, not a validated response surface or evidence of a particular mode shape.", ...
    ["map_min_mean_g","map_min_mass_kg","map_min_position","map_min_pwm","map_max_mean_g","map_max_mass_kg","map_max_position","map_max_pwm","map_max_min_factor"], ...
    [lo,keys(il,:),hi,keys(ih,:),hi/lo]);
non=find(isfinite(M.load_kg)&isfinite(M.vibration_pwm)&~ismember(M.category,["Wind","Impact"]));
desc(31,"The combined campaign supplies %d observed mass/position/PWM combinations, but no unloaded baseline from that same batch. Temperature is observed rather than independently balanced, and T0236 has no temperature measurements at all. Consequently the apparent coverage of %d non-disturbance recordings cannot identify separate load, command and environmental effects without stratification. A future model needs deliberately matched baselines and independent thermal sessions, not simply more samples at already populated settings.", ...
    ["combined_condition_cells","known_non_disturbance_runs"],[size(keys,1),numel(non)]);
desc(32,"The quality summary exposes two different risks: %d load-cell entries in %d recordings meet the extreme-value audit threshold, while every retained recording has timestamp gaps. The largest thermal left-cell value is %.3g times its run median, incompatible with treating a simple average as a representative baseline without investigation. Median summaries limit isolated-artifact influence but cannot restore lost dynamics or certify accuracy. High finite coverage and stable medians therefore do not remove the need for acquisition repair, calibration and sample-level cleaning provenance.", ...
    ["extreme_entries","extreme_recordings","thermal2_max_to_median"],[sum(M.lc_extreme_count),nnz(M.lc_extreme_count),M.lc_left_max(t2)/M.lc_left_median(t2)]);
if any(P.figure_id=="F33")
    s=S{tc}; band=find(s.f>=.5&s.f<=40); [~,order]=sort(s.amplitude(band),'descend'); second=band(order(2));
    half=floor(s.N/2); a=sqrt(mean(s.residual(1:half).^2)); b=sqrt(mean(s.residual(half+1:end).^2));
    desc(33,"The accepted interval contains %d source samples and %d uniformly resampled values at %.3f Hz. Its %.3f s source span yields FFT bin spacing %.4f Hz. The largest searched response bin is %.4f Hz at %.6f g, but the adjacent %.4f Hz bin is only %.1f percent smaller. These bins lie within one Hann main lobe, so the result supports a broad low-frequency response region, not two resolved tones or a uniquely identified structural mode. First/second-half dynamic RMS is %.5f/%.5f g, indicating some within-interval variation. Slow modulation, structural motion or excitation variability are plausible; PWM 64 supplies no physical frequency calibration. With no input force, temperature data or independent repeat spectrum, neither resonance nor damping is validated.", ...
        ["source_samples","uniform_samples","fs_Hz","source_duration_s","df_Hz","peak_Hz","peak_g","adjacent_Hz","adjacent_decrease_pct","first_half_rms_g","second_half_rms_g"], ...
        [s.sourceN,s.N,s.fs,s.duration,s.df,s.peakHz,s.peakAmplitude,s.f(second),100*(1-s.amplitude(second)/s.peakAmplitude),a,b]);
end
assert(all(strlength(P.engineering_analysis)>0),'Every figure requires an engineering interpretation.');
P.calculated_numerical_findings=P.engineering_analysis;
writetable(struct2table(evidence),fullfile(out,'analysis_evidence.csv'));
writetable(P(:,{'figure_id','engineering_analysis'}),fullfile(out,'figure_discussions.csv'));

    function ix=sourceRows(id)
        row=find(P.figure_id==sprintf('F%02d',id)); paths=split(P.source_cleaned_csv_files(row),'; ');
        ix=find(ismember("cleaned_data/"+M.run_id,paths)); assert(numel(ix)==P.source_count(row));
    end
    function desc(id,format,labels,values)
        row=find(P.figure_id==sprintf('F%02d',id)); assert(isscalar(row));
        assert(numel(labels)==numel(values) && all(isfinite(values)),'Invalid numerical analysis evidence for F%02d.',id);
        args=num2cell(values); P.engineering_analysis(row)=string(sprintf(format,args{:}));
        for q=1:numel(values)
            evidence(end+1)=struct('figure_id',P.figure_id(row),'metric',labels(q),'value',values(q), ...
                'source_cleaned_csv_files',P.source_cleaned_csv_files(row)); %#ok<AGROW>
        end
    end
end
